// A settle condition rather than a delay: post_init has been entered, the
// frame is out of post_init's Freeze/Thaw, and the loop has delivered a
// further wxEVT_IDLE since -- which it only does once nothing is pending:
// no queued page change, no CallAfter, no timer already due. The watcher
// is bound on the app after GUI_App's own idle handler, so wx runs it
// first in the same event; arming only after post_initialized() is seen
// is what keeps the idle that ran post_init from counting.
void wait_until_settled(std::string name, std::function<void()> then)
{
    if (!m_idle_watch_bound) {
        m_app.Bind(wxEVT_IDLE, [weak = std::weak_ptr<Scenario>(shared_from_this())](wxIdleEvent& event) {
            if (auto self = weak.lock(); self && self->m_idle_armed)
                self->m_idle_seen = true;
            event.Skip();
        });
        m_idle_watch_bound = true;
    }
    m_idle_armed = false;
    m_idle_seen  = false;
    wait_until([this] {
        if (!m_app.post_initialized() || m_frame->IsFrozen())
            return false;
        if (!m_idle_armed) {
            m_idle_armed = true;
            return false;
        }
        return m_idle_seen;
    }, std::move(name), std::move(then));
}

std::string OrcaHomeBackend::connect_printer(const std::string& printer_id)
{
    const auto name = strip(printer_id, kNamedPrefix);
    if (!name)
        return gone();
    const auto saved = Printers::named_printers();
    if (std::none_of(saved.begin(), saved.end(), [&](const auto& printer) { return printer.name == *name; }))
        return gone();
    if (m_open_conversation)
        m_open_conversation(*name, true);
    return {};
}

std::string OrcaHomeBackend::calibrate_printer(const std::string& printer_id)
{
    const auto name = strip(printer_id, kNamedPrefix);
    if (!name)
        return gone();
    const auto saved = Printers::named_printers();
    if (std::none_of(saved.begin(), saved.end(), [&](const auto& printer) { return printer.name == *name; }))
        return gone();
    // Its loaded spools, as the card shows them, for the person to say which
    // one the test is for.
    std::vector<std::string> spools;
    for (const PrinterEntry& printer : printers())
        if (printer.id == printer_id)
            for (const SpoolEntry& spool : printer.spools)
                spools.push_back(spool.material + (spool.colour.empty() || spool.material.empty() ? "" : " ") + spool.colour);
    if (m_start_calibration)
        m_start_calibration(*name, spools);
    return {};
}

